// Safety checks for unstable raw ZeroAI outputs. No external AI/API.
export function checkGeneratedQuality(text){
  const raw=String(text||'');
  if(!raw.trim())return {ok:false,code:'empty',reason:'回答が空になりました'};
  // TextDecoder produces U+FFFD if generated bytes are not valid UTF-8.
  if(raw.includes('\uFFFD'))return {ok:false,code:'invalid_utf8',reason:'生成されたバイト列を日本語として正しく読み取れませんでした'};
  const normalized=raw.replace(/[\s、，,.。！!？?「」『』（）()]/gu,'');
  // A definite, contiguous loop (3 or more copies of a >=2-char substring).
  for(let len=2;len<=Math.min(24,Math.floor(normalized.length/3));len++){
    for(let at=0;at+3*len<=normalized.length;at++){
      const part=normalized.slice(at,at+len);
      if(part!==normalized.slice(at+len,at+2*len)||
         part!==normalized.slice(at+2*len,at+3*len))continue;
      // Exclude trivial repeating-character patterns like ーーー.
      if(new Set([...part]).size<2)continue;
      return {ok:false,code:'repetition_loop',reason:'同じ言葉の繰り返しを検出しました'};
    }
  }
  return {ok:true,code:'ok',reason:''};
}
